import {VectorTile} from '@mapbox/vector-tile';
import {PbfReader} from 'pbf';

/** Decode already-decompressed MVT bytes; GeoJSON projection and ring handling
 * use @mapbox/vector-tile.toGeoJSON without geometry simplification.
 * Optional {layers: ['building']} limits conversion to named source layers.
 */
export function decodeTile(arrayBuffer, x, y, z, options = {}) {
  if (![x, y, z].every(Number.isInteger) || z < 0 || z > 30 || x < 0 || y < 0 || x >= 2 ** z || y >= 2 ** z) {
    throw new RangeError('Valid integer XYZ tile coordinates are required.');
  }
  const bytes = arrayBuffer instanceof Uint8Array ? arrayBuffer
    : ArrayBuffer.isView(arrayBuffer) ? new Uint8Array(arrayBuffer.buffer, arrayBuffer.byteOffset, arrayBuffer.byteLength)
    : new Uint8Array(arrayBuffer);
  const tile = new VectorTile(new PbfReader(bytes));
  const requested = options.layers ? new Set(options.layers) : null;
  const features = [];
  for (const [name, layer] of Object.entries(tile.layers)) {
    if (requested && !requested.has(name)) continue;
    for (let i = 0; i < layer.length; i++) {
      const feature = layer.feature(i).toGeoJSON(x, y, z);
      feature.sourceLayer = name;
      feature.properties = {...feature.properties};
      if (!Object.hasOwn(feature.properties, '__sourceLayer')) feature.properties.__sourceLayer = name;
      features.push(feature);
    }
  }
  return {type: 'FeatureCollection', features};
}
export {VectorTile, PbfReader, PbfReader as Pbf};
